{"command": "cd /workspace/vllm-project/tmp && cat > make_json.py << 'EOF'
import json
import os

def read_file(path):
    with open(path, 'r') as f:
        return f.read()

kernel3d = read_file('kernel3d.py')
reduce_seg = read_file('reduce_segments_complete.py')

output = {
    "vllm/attention/ops/triton_unified_attention.py": {
        "kernel_unified_attention_3d": kernel3d,
        "reduce_segments": reduce_seg
    }
}

with open('/prediction.json', 'w') as f:
    json.dump(output, f, indent=2)
EOF
python make_json.py 2>&1"}

